create or replace function public.delete_account(p_organization_id uuid,p_account_id uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare v_uid uuid := (select auth.uid()); v_old jsonb; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; if not public.has_org_permission(p_organization_id,'accounts.delete') then raise exception 'FORBIDDEN'; end if; select to_jsonb(a) into v_old from public.accounts a where a.id=p_account_id and a.organization_id=p_organization_id; if v_old is null then raise exception 'ACCOUNT_NOT_FOUND'; end if; if exists(select 1 from public.accounts where parent_account_id=p_account_id) then raise exception 'ACCOUNT_HAS_CHILDREN'; end if; if exists(select 1 from public.financial_facts where account_id=p_account_id) then raise exception 'ACCOUNT_PUBLISHED'; end if; if exists(select 1 from public.budget_lines where account_id=p_account_id) then raise exception 'ACCOUNT_HAS_BUDGET_DATA'; end if; if exists(select 1 from public.forecast_lines where account_id=p_account_id) then raise exception 'ACCOUNT_HAS_FORECAST_DATA'; end if; delete from public.opening_balances where account_id=p_account_id; delete from public.account_mappings where target_account_id=p_account_id; delete from public.accounts where id=p_account_id and organization_id=p_organization_id; perform public.write_audit_event(p_organization_id,'account.delete','account',p_account_id::text,v_old,null); return true; end; $$;

create or replace function public.delete_chart_accounts(p_organization_id uuid,p_account_ids uuid[]) returns integer language plpgsql security definer set search_path='' as $$ declare v_uid uuid := (select auth.uid()); v_count integer; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; if not public.has_org_permission(p_organization_id,'accounts.delete') then raise exception 'FORBIDDEN'; end if; if p_account_ids is null or cardinality(p_account_ids)=0 then raise exception 'NO_ACCOUNTS_SELECTED'; end if; if exists(select 1 from public.accounts a where a.organization_id=p_organization_id and a.id=any(p_account_ids) and exists(select 1 from public.financial_facts f where f.account_id=a.id)) then raise exception 'ACCOUNT_PUBLISHED'; end if; if exists(select 1 from public.accounts a where a.organization_id=p_organization_id and a.id=any(p_account_ids) and exists(select 1 from public.budget_lines b where b.account_id=a.id)) then raise exception 'ACCOUNT_HAS_BUDGET_DATA'; end if; if exists(select 1 from public.accounts a where a.organization_id=p_organization_id and a.id=any(p_account_ids) and exists(select 1 from public.forecast_lines f where f.account_id=a.id)) then raise exception 'ACCOUNT_HAS_FORECAST_DATA'; end if; if exists(select 1 from public.accounts c where c.organization_id=p_organization_id and c.parent_account_id=any(p_account_ids) and not(c.id=any(p_account_ids))) then raise exception 'ACCOUNT_HAS_CHILDREN'; end if; delete from public.opening_balances where account_id=any(p_account_ids); delete from public.account_mappings where target_account_id=any(p_account_ids); delete from public.accounts where organization_id=p_organization_id and id=any(p_account_ids); get diagnostics v_count=row_count; return v_count; end; $$;

create or replace function public.delete_entire_chart_of_accounts(p_organization_id uuid) returns integer language plpgsql security definer set search_path='' as $$ declare v_uid uuid := (select auth.uid()); v_count integer; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; if not public.has_org_permission(p_organization_id,'accounts.delete') then raise exception 'FORBIDDEN'; end if; if exists(select 1 from public.financial_facts where organization_id=p_organization_id) then raise exception 'CHART_HAS_PUBLISHED_DATA'; end if; if exists(select 1 from public.budget_lines b join public.accounts a on a.id=b.account_id where a.organization_id=p_organization_id) then raise exception 'CHART_HAS_BUDGET_DATA'; end if; if exists(select 1 from public.forecast_lines f join public.accounts a on a.id=f.account_id where a.organization_id=p_organization_id) then raise exception 'CHART_HAS_FORECAST_DATA'; end if; delete from public.opening_balances ob using public.accounts a where ob.account_id=a.id and a.organization_id=p_organization_id; delete from public.account_mappings am using public.accounts a where am.target_account_id=a.id and a.organization_id=p_organization_id; delete from public.accounts where organization_id=p_organization_id; get diagnostics v_count=row_count; return v_count; end; $$;

revoke all on function public.delete_account(uuid,uuid) from public,anon; grant execute on function public.delete_account(uuid,uuid) to authenticated;
revoke all on function public.delete_chart_accounts(uuid,uuid[]) from public,anon; grant execute on function public.delete_chart_accounts(uuid,uuid[]) to authenticated;
revoke all on function public.delete_entire_chart_of_accounts(uuid) from public,anon; grant execute on function public.delete_entire_chart_of_accounts(uuid) to authenticated;